class Solution:
    def onceTwice(self, nums: List[int]) -> List[int]:
        once = twice = 0
        for b in range(32):
            c = sum((x >> b) & 1 for x in nums)
            if c % 3 == 1: once |= 1 << b
            elif c % 3 == 2: twice |= 1 << b
        if once >> 31: once -= 1 << 32
        if twice >> 31: twice -= 1 << 32
        return [once, twice]

