        for (int b = 0; b < 32; b++) {
            int c = 0;
            for (int x : nums) c += (x >> b) & 1;
            if (c % 3 == 1) once |= 1u << b;
            else if (c % 3 == 2) twice |= 1u << b;
        }
        return {once, twice};
    }
};

